import sqlite3
import threading


class NotesStore:
    def __init__(self, path):
        self._lock = threading.RLock()
        self._conn = sqlite3.connect(
            path,
            timeout=5.0,
            isolation_level=None,
            check_same_thread=False,
        )
        with self._lock:
            self._conn.execute('PRAGMA busy_timeout = 5000')
            self._conn.execute(
                'CREATE TABLE IF NOT EXISTS notes ('
                'id INTEGER PRIMARY KEY AUTOINCREMENT, '
                'owner_id TEXT NOT NULL, '
                'request_id TEXT NOT NULL, '
                'text TEXT NOT NULL, '
                'UNIQUE(owner_id, request_id)'
                ')'
            )

    @staticmethod
    def _require_caller(caller):
        if not isinstance(caller, str) or caller == '':
            raise ValueError('caller must be a nonempty owner ID')

    @staticmethod
    def _require_request_id(request_id):
        if request_id is None:
            raise ValueError('request_id is required')

    @staticmethod
    def _require_text(text):
        if not isinstance(text, str) or not text.strip():
            raise ValueError('text must contain a non-whitespace character')

    @staticmethod
    def _note(row):
        return {'id': row[0], 'owner_id': row[1], 'text': row[2]}

    def create(self, caller, request_id, text):
        self._require_caller(caller)
        self._require_request_id(request_id)
        with self._lock:
            self._conn.execute('BEGIN IMMEDIATE')
            try:
                row = self._conn.execute(
                    'SELECT id, owner_id, text FROM notes '
                    'WHERE owner_id = ? AND request_id = ?',
                    (caller, request_id),
                ).fetchone()
                if row is not None:
                    self._conn.execute('COMMIT')
                    return self._note(row)

                self._require_text(text)
                self._conn.execute(
                    'INSERT INTO notes(owner_id, request_id, text) '
                    'VALUES (?, ?, ?) '
                    'ON CONFLICT(owner_id, request_id) DO NOTHING',
                    (caller, request_id, text),
                )
                row = self._conn.execute(
                    'SELECT id, owner_id, text FROM notes '
                    'WHERE owner_id = ? AND request_id = ?',
                    (caller, request_id),
                ).fetchone()
                if row is None:
                    raise RuntimeError('creation did not produce a note')
                self._conn.execute('COMMIT')
                return self._note(row)
            except BaseException:
                if self._conn.in_transaction:
                    self._conn.execute('ROLLBACK')
                raise

    def read(self, caller, note_id):
        self._require_caller(caller)
        with self._lock:
            row = self._conn.execute(
                'SELECT id, owner_id, text FROM notes '
                'WHERE id = ? AND owner_id = ?',
                (note_id, caller),
            ).fetchone()
        if row is None:
            raise PermissionError('note is unavailable')
        return self._note(row)

