                    'WHERE id = ? AND owner_id = ?',
                    (note_id, caller),
                ).fetchone()
                self._conn.execute('COMMIT')
                return self._note(row)
            except BaseException:
                if self._conn.in_transaction:
                    self._conn.execute('ROLLBACK')
